                    JSON.toJSONString(paramDto), JSON.toJSONString(claimCareApplyContext), e);
            return claimCareApplyContext.getClaimCareOperationResultDTO();
        } catch (Exception e) {
            log.error("updateClaimCareOrder encountered Exception, with paramDto is {}", JSON.toJSONString(paramDto), e);
            throw e;
        }
    }

private ClaimCareApplyContext buildClaimCareApplyContextForUpdate(ClaimCareOrderDTO paramDto, ClaimCareApplyContext claimCareApplyContext, String policyNoRequestHeader) {
        ClaimCareOrderDTO queryDto = queryClaimCareOrderDetail(paramDto.getReportNo(), policyNoRequestHeader);
        claimCareApplyContext.setQueryDto(queryDto);

        // 订单列表
        List<ClaimCareReportDTO> claimCareReportDTOS = externalCarClaimCareService.qryValueAddedServiceList(queryDto.getPolicyNo());
        claimCareApplyContext.setClaimCareReportDTOS(claimCareReportDTOS);

        // 保单详情
        CarPolicyDetailBean carPolicyDetailBean = queryPolicy(queryDto.getPolicyNo());
        // 这里看历史的代码 BusinessDate 和 contract 都是取的第一个
        BusinessDate businessDate = carPolicyDetailBean.getBusinessDate().get(0);
        Coverage coverage = getCoverage(businessDate, queryDto.getServiceType());
        claimCareApplyContext.setServiceItemCode(ClaimCareAssembler.toServiceItemCode(coverage.getKindCode(), queryDto.getServiceCategories()));
        return claimCareApplyContext;
    }

private void updateClaimCareValidate(ClaimCareOrderDTO paramDto, ClaimCareApplyContext claimCareApplyContext) {
        ClaimCareOrderDTO queryDto = claimCareApplyContext.getQueryDto();

        if (ClaimCareServiceTypeEnum.RIDE_HAILING.getCode().equals(queryDto.getServiceType()) || ClaimCareServiceTypeEnum.SECURITY_CHECK.getCode().equals(queryDto.getServiceType())) {
            log.error("不允许修改操作！报案号:{}", queryDto.getReportNo());
            ExceptionUtils.throwFailureException(ErrorEnum.CLAIM_CARE_NOT_ALLOW_MODIFY, "不允许修改操作！");
        }

        if(!ApplyChannelEnum.SUPPORT_CHANNEL.contains(queryDto.getApplyChannel())){
            log.error("该渠道不能修改已有的增值服务订单,，request:{}", JSONObject.toJSONString(paramDto));
            ExceptionUtils.throwFailureException(ErrorEnum.SYS_INNER_DB_NOT_EXIST, "该渠道不能修改已有的增值服务订单");
        }

        //参数必填校验
        updateBaseValidate(paramDto);

        // 可修改时间和状态校验
        Integer orderStatus = Integer.parseInt(queryDto.getSubOrderStatus());
        // 校验距离服务申请时间大于3分钟
        if (DateUtils.getMinutesBetween(DateUtils.dateParse(queryDto.getApplyTime()), new Date()) > getUpdateTimeOut(queryDto.getServiceType())) {
            log.error("修改已有的增值服务订单, 服务申请时间大于3分钟:{}", JSON.toJSONString(queryDto));
            ExceptionUtils.throwFailureException(ErrorEnum.REQUEST_PARAMETERS_ERROR, "修改已有的增值服务订单,服务申请时间大于" + getUpdateTimeOut(queryDto.getServiceType()) + "分钟");
        } else {
            // 校验距离服务申请时间小于3分钟 && 订单状态已出发
            if (orderStatus >= canUpdateMinStatus(queryDto.getServiceType())) {
                log.error("修改已有的增值服务订单, 服务申请时间小于3分钟 && 订单状态已出发:{}", JSON.toJSONString(queryDto));
                ExceptionUtils.throwFailureException(ErrorEnum.REQUEST_PARAMETERS_ERROR, "当前状态不允许修改");
            }
        }

        // 地区校验
        // 设置已有信息
        paramDto.setServiceTime(queryDto.getServiceTime());
        paramDto.setPolicyNo(queryDto.getPolicyNo());
        paramDto.setServiceType(queryDto.getServiceType());
        paramDto.setServiceCategories(queryDto.getServiceCategories());
        // 地区校验会在上下文中设置  距离
        areaValidate(paramDto, claimCareApplyContext);
        if (ClaimCareServiceTypeEnum.ROADSIDE_ASSISTANCE.getCode().equals(queryDto.getServiceType())) {
            // 道路救援校验-服务地址关键字校验
            serviceAddressKeywordValidate(paramDto);

            // 道路救援校验-拖车校验
            if (isRescueTrailer(queryDto.getServiceCategories())) {
                // 目的地地址关键字校验
                expDestAddressKeywordValidate(paramDto);

                // 50km 校验
                trailerMaxDistanceValidate(paramDto, claimCareApplyContext, queryDto.getServiceType());
            }
        } else if (ClaimCareServiceTypeEnum.ANNUAL_INSPECTION_PROXY.getCode().equals(queryDto.getServiceType())) {
            //预约时间校验
            paramDto.setApplyTime(queryDto.getApplyTime());
            annualInspectionProxyTimeValidate(paramDto);
        }
    }

